<title>ChartPulse — Track All Markets</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #0a0a12;
    --bg-card: #111120;
    --bg-elevated: #16162a;
    --bg-hover: #1c1c32;
    --border: #222240;
    --border-light: #2a2a50;
    --text: #e4e4f0;
    --text-2: #9090b0;
    --text-3: #55557a;
    --blue: #2962ff;
    --blue-hover: #3d74ff;
    --blue-dim: rgba(41,98,255,0.15);
    --green: #00c805;
    --green-dim: rgba(0,200,5,0.12);
    --red: #f7525f;
    --red-dim: rgba(247,82,95,0.12);
    --gold: #e8b84b;
    --radius: 6px;
    --radius-lg: 10px;
  }
  html { scroll-behavior: smooth; }
  body { background: var(--bg); color: var(--text); font-family: 'Inter', sans-serif; font-size: 13px; line-height: 1.5; overflow-x: hidden; }
  a { color: inherit; text-decoration: none; }
  button { font-family: inherit; cursor: pointer; border: none; background: none; }

  /* NAV */
  nav { position: sticky; top: 0; z-index: 100; background: rgba(10,10,18,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); height: 48px; display: flex; align-items: center; padding: 0 20px; gap: 0; }
  .nav-logo { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 15px; color: var(--text); margin-right: 32px; white-space: nowrap; }
  .nav-logo span { color: var(--blue); }
  .nav-logo svg { color: var(--blue); }
  .nav-links { display: flex; gap: 4px; flex: 1; }
  .nav-links a { padding: 6px 12px; color: var(--text-2); font-size: 13px; font-weight: 500; border-radius: var(--radius); transition: all 0.15s; }
  .nav-links a:hover, .nav-links a.active { background: var(--bg-hover); color: var(--text); }
  .nav-actions { display: flex; align-items: center; gap: 8px; }
  .btn-ghost { padding: 6px 14px; color: var(--text-2); font-size: 13px; font-weight: 500; border-radius: var(--radius); border: 1px solid var(--border); transition: all 0.15s; }
  .btn-ghost:hover { background: var(--bg-hover); color: var(--text); border-color: var(--border-light); }
  .btn-primary { padding: 6px 16px; background: var(--blue); color: #fff; font-size: 13px; font-weight: 600; border-radius: var(--radius); transition: all 0.15s; }
  .btn-primary:hover { background: var(--blue-hover); }

  /* TICKER BAR */
  .ticker-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); overflow: hidden; height: 34px; display: flex; align-items: center; }
  .ticker-scroll { display: flex; gap: 0; animation: scroll-left 60s linear infinite; white-space: nowrap; }
  .ticker-bar:hover .ticker-scroll { animation-play-state: paused; }
  @keyframes scroll-left { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
  .ticker-item { display: inline-flex; align-items: center; gap: 8px; padding: 0 20px; border-right: 1px solid var(--border); height: 34px; font-size: 12px; }
  .ticker-symbol { font-weight: 600; color: var(--text); }
  .ticker-price { color: var(--text-2); }
  .tick-up { color: var(--green); }
  .tick-down { color: var(--red); }

  /* MARKET SUMMARY */
  .market-summary { background: var(--bg-card); border-bottom: 1px solid var(--border); }
  .tabs { display: flex; gap: 0; padding: 0 20px; border-bottom: 1px solid var(--border); overflow-x: auto; }
  .tabs::-webkit-scrollbar { height: 0; }
  .tab-btn { padding: 10px 16px; font-size: 13px; font-weight: 500; color: var(--text-3); background: none; border: none; border-bottom: 2px solid transparent; cursor: pointer; white-space: nowrap; transition: all 0.15s; }
  .tab-btn:hover { color: var(--text-2); }
  .tab-btn.active { color: var(--text); border-bottom-color: var(--blue); }
  .tab-panel { display: none; padding: 12px 20px; }
  .tab-panel.active { display: block; }

  /* MARKET GRID */
  .market-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 8px; }
  .market-card { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius); padding: 10px 12px; display: flex; flex-direction: column; gap: 4px; cursor: pointer; transition: border-color 0.15s; }
  .market-card:hover { border-color: var(--blue); }
  .mc-name { font-size: 11px; color: var(--text-3); font-weight: 500; }
  .mc-ticker { font-size: 11px; color: var(--text-2); }
  .mc-price { font-size: 15px; font-weight: 600; color: var(--text); }
  .mc-change { font-size: 12px; font-weight: 600; padding: 2px 6px; border-radius: 4px; display: inline-block; width: fit-content; }
  .mc-change.up { background: var(--green-dim); color: var(--green); }
  .mc-change.down { background: var(--red-dim); color: var(--red); }
  .mc-chart { margin-top: 4px; }

  /* SPARKLINE */
  .spark { display: block; }

  /* HERO */
  .hero { padding: 72px 40px 64px; max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
  .hero-tag { display: inline-flex; align-items: center; gap: 6px; background: var(--blue-dim); color: var(--blue); font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 20px; border: 1px solid rgba(41,98,255,0.3); margin-bottom: 20px; letter-spacing: 0.5px; text-transform: uppercase; }
  .hero h1 { font-size: 42px; font-weight: 700; line-height: 1.15; color: var(--text); margin-bottom: 16px; letter-spacing: -0.5px; }
  .hero h1 em { color: var(--blue); font-style: normal; }
  .hero p { font-size: 16px; color: var(--text-2); line-height: 1.6; margin-bottom: 28px; }
  .hero-btns { display: flex; gap: 12px; flex-wrap: wrap; }
  .btn-lg { padding: 12px 24px; font-size: 14px; font-weight: 600; border-radius: var(--radius); transition: all 0.15s; }
  .btn-lg.primary { background: var(--blue); color: #fff; }
  .btn-lg.primary:hover { background: var(--blue-hover); transform: translateY(-1px); box-shadow: 0 4px 20px rgba(41,98,255,0.4); }
  .btn-lg.outline { background: none; color: var(--text-2); border: 1px solid var(--border-light); }
  .btn-lg.outline:hover { background: var(--bg-hover); color: var(--text); }
  .hero-stat { display: flex; flex-direction: column; }
  .hero-stat-val { font-size: 28px; font-weight: 700; color: var(--text); }
  .hero-stat-label { font-size: 12px; color: var(--text-3); }
  .hero-stats { display: flex; gap: 32px; margin-top: 28px; padding-top: 24px; border-top: 1px solid var(--border); }
  .hero-visual { display: flex; flex-direction: column; gap: 8px; }
  .hero-chart-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }
  .hcc-header { padding: 10px 14px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--border); }
  .hcc-sym { font-weight: 700; font-size: 14px; }
  .hcc-price { font-size: 16px; font-weight: 700; }
  .hcc-body { padding: 4px 0 8px; }

  /* SECTION */
  .section { padding: 40px 20px; max-width: 1200px; margin: 0 auto; }
  .section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
  .section-title { font-size: 18px; font-weight: 700; color: var(--text); }
  .section-link { font-size: 12px; color: var(--blue); font-weight: 500; }
  .section-link:hover { text-decoration: underline; }

  /* IDEAS CARDS */
  .ideas-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 12px; }
  .idea-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; transition: border-color 0.15s; cursor: pointer; }
  .idea-card:hover { border-color: var(--border-light); }
  .idea-img { height: 140px; background: var(--bg-elevated); position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; }
  .idea-chart-preview { width: 100%; padding: 10px; }
  .idea-body { padding: 12px; }
  .idea-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
  .idea-avatar { width: 24px; height: 24px; border-radius: 50%; background: var(--blue-dim); display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; color: var(--blue); }
  .idea-user { font-size: 12px; color: var(--text-2); font-weight: 500; }
  .idea-sym-badge { margin-left: auto; font-size: 10px; font-weight: 700; background: var(--bg-elevated); color: var(--text-2); padding: 2px 6px; border-radius: 4px; border: 1px solid var(--border); }
  .idea-title { font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 6px; line-height: 1.4; }
  .idea-desc { font-size: 12px; color: var(--text-3); line-height: 1.5; }
  .idea-footer { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-top: 1px solid var(--border); }
  .idea-tag { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }
  .idea-tag.bull { color: var(--green); background: var(--green-dim); padding: 2px 6px; border-radius: 4px; }
  .idea-tag.bear { color: var(--red); background: var(--red-dim); padding: 2px 6px; border-radius: 4px; }
  .idea-tag.neutral { color: var(--gold); background: rgba(232,184,75,0.1); padding: 2px 6px; border-radius: 4px; }
  .idea-likes { margin-left: auto; font-size: 11px; color: var(--text-3); display: flex; align-items: center; gap: 4px; }

  /* TRENDING STOCKS */
  .trending-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 8px; }
  .stock-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px; display: flex; align-items: center; gap: 10px; cursor: pointer; transition: border-color 0.15s; }
  .stock-card:hover { border-color: var(--blue); }
  .stock-rank { font-size: 11px; color: var(--text-3); font-weight: 600; min-width: 16px; }
  .stock-info { flex: 1; min-width: 0; }
  .stock-sym { font-size: 13px; font-weight: 700; color: var(--text); }
  .stock-name { font-size: 11px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .stock-right { text-align: right; }
  .stock-price { font-size: 13px; font-weight: 600; color: var(--text); }
  .stock-chg { font-size: 11px; font-weight: 600; }
  .stock-chg.up { color: var(--green); }
  .stock-chg.down { color: var(--red); }

  /* TOP STORIES */
  .stories-list { display: flex; flex-direction: column; gap: 0; }
  .story-item { display: flex; align-items: center; gap: 16px; padding: 14px 0; border-bottom: 1px solid var(--border); cursor: pointer; transition: opacity 0.15s; }
  .story-item:hover { opacity: 0.8; }
  .story-item:last-child { border-bottom: none; }
  .story-source { font-size: 11px; color: var(--blue); font-weight: 600; white-space: nowrap; min-width: 80px; }
  .story-title { font-size: 13px; color: var(--text); font-weight: 500; flex: 1; }
  .story-time { font-size: 11px; color: var(--text-3); white-space: nowrap; }

  /* INDICATORS */
  .indicators-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 8px; }
  .indicator-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px; display: flex; align-items: center; gap: 12px; cursor: pointer; transition: border-color 0.15s; }
  .indicator-card:hover { border-color: var(--border-light); }
  .ind-icon { width: 36px; height: 36px; border-radius: var(--radius); background: var(--blue-dim); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .ind-info { flex: 1; }
  .ind-name { font-size: 13px; font-weight: 600; color: var(--text); }
  .ind-author { font-size: 11px; color: var(--text-3); }
  .ind-stars { font-size: 11px; color: var(--gold); }

  /* TRADE IDEAS */
  .trade-table { width: 100%; border-collapse: collapse; }
  .trade-table th { text-align: left; padding: 8px 12px; font-size: 11px; font-weight: 600; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid var(--border); background: var(--bg-card); }
  .trade-table td { padding: 10px 12px; font-size: 13px; border-bottom: 1px solid var(--border); vertical-align: middle; }
  .trade-table tr:hover td { background: var(--bg-hover); }
  .trade-table tr:last-child td { border-bottom: none; }
  .tt-sym { font-weight: 700; color: var(--text); }
  .tt-name { font-size: 11px; color: var(--text-3); }
  .tt-dir { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px; }
  .tt-dir.buy { background: var(--green-dim); color: var(--green); }
  .tt-dir.sell { background: var(--red-dim); color: var(--red); }

  /* FOOTER */
  footer { background: var(--bg-card); border-top: 1px solid var(--border); padding: 48px 40px 24px; }
  .footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 32px; max-width: 1200px; margin: 0 auto 40px; }
  .footer-col h4 { font-size: 12px; font-weight: 700; color: var(--text); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px; }
  .footer-col a { display: block; font-size: 12px; color: var(--text-3); margin-bottom: 8px; transition: color 0.15s; }
  .footer-col a:hover { color: var(--text-2); }
  .footer-bottom { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; padding-top: 24px; border-top: 1px solid var(--border); }
  .footer-logo { font-weight: 700; font-size: 14px; }
  .footer-logo span { color: var(--blue); }
  .footer-copy { font-size: 11px; color: var(--text-3); }

  /* STATS BAR */
  .stats-bar { background: linear-gradient(135deg, #1a1a3e 0%, #0d1a3a 100%); border: 1px solid rgba(41,98,255,0.2); border-radius: var(--radius-lg); padding: 32px 40px; display: flex; align-items: center; justify-content: center; gap: 60px; text-align: center; margin: 0 20px; }
  .stats-bar-item { display: flex; flex-direction: column; align-items: center; gap: 4px; }
  .stats-bar-val { font-size: 32px; font-weight: 700; color: var(--blue); }
  .stats-bar-label { font-size: 13px; color: var(--text-2); }
  .stats-bar-divider { width: 1px; height: 48px; background: var(--border); }

  /* BADGE */
  .badge { font-size: 10px; font-weight: 700; padding: 2px 6px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
  .badge-blue { background: var(--blue-dim); color: var(--blue); }
  .badge-green { background: var(--green-dim); color: var(--green); }
  .badge-red { background: var(--red-dim); color: var(--red); }

  .table-wrapper { overflow-x: auto; border-radius: var(--radius); border: 1px solid var(--border); }
  .data-table { width: 100%; border-collapse: collapse; }
  .data-table th { padding: 10px 14px; font-size: 11px; font-weight: 600; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid var(--border); background: var(--bg-card); text-align: left; }
  .data-table td { padding: 10px 14px; font-size: 13px; border-bottom: 1px solid var(--border); vertical-align: middle; }
  .data-table tbody tr:hover td { background: var(--bg-hover); cursor: pointer; }
  .data-table tbody tr:last-child td { border-bottom: none; }
  .col-up { color: var(--green); font-weight: 600; }
  .col-down { color: var(--red); font-weight: 600; }
  .col-sym { font-weight: 700; color: var(--text); }

  /* CRYPTO CARDS */
  .crypto-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 8px; }
  .crypto-card { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px; }
  .cc-label { font-size: 11px; color: var(--text-3); margin-bottom: 4px; }
  .cc-val { font-size: 18px; font-weight: 700; color: var(--text); }
  .cc-chg { font-size: 12px; font-weight: 600; margin-top: 2px; }

  @media (max-width: 768px) {
    .hero { grid-template-columns: 1fr; padding: 40px 20px; }
    .hero-visual { display: none; }
    .hero h1 { font-size: 28px; }
    nav { padding: 0 12px; }
    .nav-links a:nth-child(n+3) { display: none; }
    .stats-bar { flex-direction: column; gap: 24px; padding: 24px; }
    .stats-bar-divider { display: none; }
    footer { padding: 32px 20px 20px; }
  }
</style>
</head>
