      const tabId = btn.dataset.tab;
      const group = btn.dataset.group;
      const parent = btn.closest('.market-summary, .section, div');

      // Find sibling tabs in same container
      const container = btn.closest('[id]') ? btn.closest('[id]').parentElement : btn.parentElement.closest('.section, .market-summary');

      // Deactivate all tabs in same tab group
      if (group) {
        document.querySelectorAll(`.tab-btn[data-group="${group}"]`).forEach(t => t.classList.remove('active'));
        document.querySelectorAll(`[id^="tab-${group}-"], [id^="tab-ind-"], [id^="tab-ideas-"]`).forEach(p => {
          const id = p.id.replace('tab-','');
          if (document.querySelector(`[data-tab="${id}"][data-group="${group}"]`)) p.classList.remove('active');
        });
      } else {
        // Tabs in same tabs container
        const tabsContainer = btn.closest('.tabs');
        tabsContainer.querySelectorAll('.tab-btn').forEach(t => t.classList.remove('active'));
        // Hide all sibling panels
        const msContainer = btn.closest('.market-summary');
        if (msContainer) msContainer.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
      }

      btn.classList.add('active');
      const panel = document.getElementById('tab-' + tabId);
      if (panel) panel.classList.add('active');
    });
