  .detail-sym { font-size: 13px; font-weight: 700; color: var(--text); }
  .detail-name { font-size: 11px; color: var(--text-3); margin-bottom: 8px; }
  .detail-price-row { display: flex; align-items: baseline; gap: 8px; margin-bottom: 4px; }
