  .detail-currency { font-size: 11px; color: var(--text-3); }
  .detail-pre { background: var(--bg-elevated); border-radius: var(--radius); padding: 6px 8px; margin-top: 8px; display: flex; align-items: center; justify-content: space-between; }
  .detail-pre-label { font-size: 11px; color: var(--text-3); }
  .detail-pre-val { font-size: 12px; font-weight: 600; color: var(--green); }
  .detail-news { background: var(--bg-elevated); border-radius: var(--radius); padding: 8px; margin-top: 8px; font-size: 11px; color: var(--text-2); line-height: 1.5; border-left: 2px solid var(--blue); }

  /* STATS TABLE */
  .stat-row { display: flex; align-items: center; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid rgba(34,34,64,0.6); }
  .stat-row:last-child { border-bottom: none; }
  .stat-label { font-size: 11px; color: var(--text-3); }
  .stat-val { font-size: 11px; font-weight: 600; color: var(--text-2); text-align: right; }
  .stat-val.up { color: var(--green); }
  .stat-val.down { color: var(--red); }
  .stat-val.neutral { color: var(--gold); }

  /* EARNINGS BADGE */
  .earnings-badge { display: inline-flex; align-items: center; gap: 4px; background: rgba(232,184,75,0.1); color: var(--gold); font-size: 11px; font-weight: 600; padding: 3px 8px; border-radius: 4px; border: 1px solid rgba(232,184,75,0.3); }

  /* PERF BARS */
  .perf-row { display: flex; align-items: center; gap: 8px; padding: 4px 0; }
  .perf-label { font-size: 11px; color: var(--text-3); min-width: 28px; }
  .perf-bar-bg { flex: 1; height: 4px; background: var(--bg-elevated); border-radius: 2px; overflow: hidden; }
  .perf-bar-fill { height: 100%; border-radius: 2px; }
  .perf-val { font-size: 11px; font-weight: 600; min-width: 44px; text-align: right; }

  /* FINANCIAL TABS */
  .fin-tabs { display: flex; gap: 0; border-bottom: 1px solid var(--border); margin-bottom: 10px; }
  .fin-tab { flex: 1; text-align: center; padding: 6px; font-size: 11px; font-weight: 600; color: var(--text-3); cursor: pointer; border-bottom: 2px solid transparent; transition: all 0.15s; }
  .fin-tab.active { color: var(--text); border-bottom-color: var(--blue); }
  .fin-panel { display: none; }
  .fin-panel.active { display: block; }

  @media (max-width: 900px) {
    .right-panel { display: none; }
    .watchlist { width: 180px; }
  }
  @media (max-width: 600px) {
    .watchlist { display: none; }
    body { overflow: auto; }
    .main { overflow: auto; }
  }
