    const rnd2 = Math.sin(seed + i * 2.3 + 1) * 0.5 + 0.5;
    const change = (rnd - 0.48) * 6;
    const open = price;
    const close = price + change;
    const high = Math.max(open, close) + rnd * 3;
    const low = Math.min(open, close) - rnd2 * 3;
