    btn.closest('.filter-bar').querySelectorAll('.filter-btn').forEach(b => {
      // Only deactivate within same group (asset type or signal type)
      if (b.closest('.filter-bar') === btn.closest('.filter-bar')) {
        const assetBtns = ['All','Stocks','Crypto','Forex','Futures','Indices'];
        const signalBtns = ['Bullish','Bearish','Neutral'];
        if (assetBtns.includes(btn.textContent.trim()) && assetBtns.includes(b.textContent.trim())) b.classList.remove('active');
        if (signalBtns.includes(btn.textContent.trim()) && signalBtns.includes(b.textContent.trim())) b.classList.remove('active');
      }
    });
    btn.classList.add('active');
