  .asset-tab.active { color: var(--text); border-bottom-color: var(--blue); }

  /* LAYOUT */
  .markets-layout { max-width: 1200px; margin: 0 auto; padding: 24px 20px; display: grid; grid-template-columns: 1fr 280px; gap: 20px; }
  .markets-main { display: flex; flex-direction: column; gap: 24px; }
  .markets-sidebar { display: flex; flex-direction: column; gap: 16px; }

  /* SECTION */
  .market-section { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; }
  .ms-header { padding: 14px 16px; border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; }
