  .er-estimate { font-size: 11px; color: var(--text-3); }
  .er-beat { color: var(--green); }
  .er-miss { color: var(--red); }

  /* BOND YIELD VISUAL */
  .yield-curve { padding: 14px; }
  .yield-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
  .yield-label { font-size: 11px; color: var(--text-3); min-width: 40px; }
  .yield-bar-bg { flex: 1; height: 6px; background: var(--bg-elevated); border-radius: 3px; overflow: hidden; }
  .yield-bar { height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--blue), #6490ff); }
  .yield-val { font-size: 12px; font-weight: 600; color: var(--text-2); min-width: 44px; text-align: right; }

  /* CRYPTO SECTION */
