  function scrollToSection(id, btn) {
    document.querySelectorAll('.asset-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function setCCBtn(btn) {
    const bar = btn.closest('div');
    const groups = [['1D','1M','3M','1Y','5Y','All'], ['Area','Candles']];
    const label = btn.textContent.trim();
    groups.forEach(group => {
      if (group.includes(label)) {
        bar.querySelectorAll('.cc-btn').forEach(b => { if (group.includes(b.textContent.trim())) b.classList.remove('active'); });
        btn.classList.add('active');
      }
    });
  }

  function switchItTab(btn, panelId) {
    const section = btn.closest('.market-section');
    section.querySelectorAll('.it-btn').forEach(b => b.classList.remove('active'));
    section.querySelectorAll('.it-panel').forEach(p => p.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(panelId).classList.add('active');
  }
