<script>
  function setCategory(btn) {
    btn.closest('div').querySelectorAll('.filter-chip').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const cat = btn.textContent.trim().toLowerCase().replace(' brokers','');
    document.querySelectorAll('.broker-card').forEach(card => {
      if (cat === 'all') {
        card.style.display = '';
      } else {
        const cats = (card.dataset.categories || '').toLowerCase();
        card.style.display = cats.includes(cat) ? '' : 'none';
      }
    });
  }

  function setRatingTab(btn) {
    btn.closest('.rating-tabs').querySelectorAll('.rt-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    // Sort cards by score when "Best rated" is selected
    const list = document.getElementById('brokerList');
    const cards = Array.from(list.querySelectorAll('.broker-card'));
    if (btn.textContent.trim() === 'Best rated') {
      cards.sort((a, b) => {
        const scoreA = parseFloat(a.querySelector('.bc-score')?.textContent || '0');
        const scoreB = parseFloat(b.querySelector('.bc-score')?.textContent || '0');
        return scoreB - scoreA;
      });
    }
    cards.forEach(card => list.appendChild(card));
  }

  function handleSort(select) {
    const list = document.getElementById('brokerList');
    const cards = Array.from(list.querySelectorAll('.broker-card'));
    const val = select.value;
    if (val.includes('reviews')) {
      cards.sort((a,b) => {
        const rA = parseFloat(a.querySelector('.bc-reviews')?.textContent || '0');
        const rB = parseFloat(b.querySelector('.bc-reviews')?.textContent || '0');
        return rB - rA;
      });
    } else if (val.includes('accounts')) {
      cards.sort((a,b) => {
        const rA = parseFloat(a.querySelector('.bc-accounts')?.textContent || '0');
        const rB = parseFloat(b.querySelector('.bc-accounts')?.textContent || '0');
        return rB - rA;
      });
    } else if (val.includes('offers')) {
      cards.sort((a,b) => {
        const hasA = a.querySelector('.bc-promo') ? 1 : 0;
        const hasB = b.querySelector('.bc-promo') ? 1 : 0;
        return hasB - hasA;
      });
    }
    cards.forEach(card => list.appendChild(card));
  }
</script>
